#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.291993485, -0.045344465, 0.040262990000000005], 'basis': [[0.0, 0.9987361043084232, -0.05026125695637145], [-0.09995872499951325, 0.05000952769976611, 0.9937340189586539], [0.9949915845355034, 0.005024051162231805, 0.09983238759765087]], 'axis': [-0.05026125695637145, 0.9937340189586539, 0.09983238759765087], 'zmin': -0.05032923062344811, 'zmax': 0.04791610897181695, 'profiles': [{'outer': [[-0.1206020412033919, 0.044200788505920866], [-0.12318985232560464, 0.060235568016270766], [-0.12574438914653954, 0.08009188220258755], [-0.1274176924185034, 0.09018283131239847], [-0.12799495124582214, 0.11096342842443845], [-0.11877612987667087, 0.12045967217008186], [-0.10651540033544596, 0.1259864183628393], [-0.09145494675857262, 0.1253090780685842], [-0.07790029175640967, 0.11818656121993291], [-0.07272908972768827, 0.09737087705527912], [-0.0709977862071241, 0.0806126641695837], [-0.07127213318864373, 0.08865677144733247], [-0.07155511641929956, 0.10225247446824438], [-0.06826479120734572, 0.11971368990121821], [-0.05570505760532873, 0.1296978783230313], [-0.04035102692650551, 0.1328339978449445], [-0.025301198070261034, 0.12820320692494316], [-0.013262445317026056, 0.11865110405185515], [-0.01177003625786653, 0.10940530826757129], [-0.00969920924766922, 0.10101437361479691], [-0.009730301336771196, 0.08826081349327126], [-0.008705077342696129, 0.09837733509359749], [-0.003738988628952931, 0.118266256184749], [0.0057514306052127125, 0.1229232806174687], [0.0096713536540657, 0.1244898688511273], [0.024205371572741795, 0.12495431073849636], [0.036537927626220434, 0.12032810244365831], [0.04594718626925591, 0.11164255893093285], [0.046829889810501055, 0.10786132517918373], [0.047474001587406126, 0.08947999601849987], [0.04376603270286947, 0.061047773808812864], [0.041249321747624405, 0.0448063767800802], [0.039098928150086656, 0.028848564327807052], [0.038470346006654166, 0.006699979527804709], [0.038522151569103005, -0.0024860317994475005], [0.03842421050241123, -0.011028267766145055], [0.038898358351824536, -0.021924694549045637], [0.04078058890796294, -0.026456925378236795], [0.04449646081222812, -0.02728366803073686], [0.05382680726902726, -0.02670790363119729], [0.06144308863806893, -0.024618931470983485], [0.06982756725489303, -0.02200580786257323], [0.08737953197566431, -0.015770963959807715], [0.09628429294655741, -0.014451107081160649], [0.10674640300615566, -0.013413589384118465], [0.10782364683823548, -0.013634108775882153], [0.12102375809544604, -0.025083885434866234], [0.1282016653978839, -0.03975168864588001], [0.12396001980960805, -0.06194323728619864], [0.10883909178598314, -0.07606403493881139], [0.08782236650926566, -0.0798270524040869], [0.07930910380718252, -0.08110827641714831], [0.0712186865378179, -0.08254785517461605], [0.06303008110404877, -0.08525820404627057], [0.055362239271096465, -0.08848605563589351], [0.03639825187505657, -0.10230419990349693], [0.023683611682601163, -0.11014107081618904], [0.012562311609625574, -0.11581991433790635], [0.0035472915626511, -0.11987422323389206], [-0.008692513235181078, -0.12388492412461939], [-0.019913589360967144, -0.1273430922454538], [-0.027855223494274065, -0.13004638281095465], [-0.03168394392418041, -0.1307073972951712], [-0.034751289055398024, -0.13143496662465778], [-0.03841217884244052, -0.13210004484199725], [-0.041851994635493675, -0.1325381102397676], [-0.04439013347988549, -0.13269911561261533], [-0.05467939808307184, -0.13201323637442156], [-0.07029525355175306, -0.12849544490315098], [-0.08513417178772091, -0.12205424300780328], [-0.0971114667012897, -0.10950482722639748], [-0.10675804436757003, -0.09345595703300115], [-0.11386250496879612, -0.07396087621706422], [-0.11787322098616493, -0.05364828741609137], [-0.11783696295784586, -0.036795187843794465], [-0.11633683544092865, -0.022169874227580745], [-0.11585254511722157, -0.00861823146214673], [-0.1174878252723167, 0.018536877862658226], [-0.1182098979653593, 0.02854762730379019]], 'holes': []}], 'simplify_tolerance': 5.310662269151196e-05, 'sketch_entity_count': 100}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
